INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish1', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":4,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'stor'?","o":["lille","tyk","gammel","tung"],"a":"lille","r":"Stor og lille er hinandens modsætninger. En elefant er stor, og en mus er lille."},
{"l":22,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Jeg er tørstig og vil have et glas ___.'","o":["vann","vand","vannd","vandd"],"a":"vand","r":"Ordet ender på nd, og d'et er stumt. Der skal kun være ét n."},
{"l":40,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Katten sover på sofaen. Den ligger på en blød pude.' Hvor sover katten?","o":["I sin kurv","Under sengen","På sofaen","På gulvet"],"a":"På sofaen","r":"Den første sætning siger det direkte: Katten sover på sofaen."},
{"l":60,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Emma råber højt: 'Pas på bilen'. Hvilket tegn viser, at hun råber?","o":["punktum","komma","spørgsmålstegn","udråbstegn"],"a":"udråbstegn","r":"Et udråbstegn viser, at nogen råber eller siger noget med stor kraft."},
{"l":83,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bedstefar har en lille båd. Hver søndag sejler han ud og fisker.' Hvad laver bedstefar om søndagen?","o":["Han fisker fra båden","Han maler sin båd","Han bager boller","Han graver i haven"],"a":"Han fisker fra båden","r":"Teksten fortæller, at han hver søndag sejler ud og fisker."},
{"l":101,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Zainab har to søskende. Hendes bror hedder Adam, og hendes søster hedder Lina.' Hvad hedder Zainabs søster?","o":["Adam","Lina","Sara","Mona"],"a":"Lina","r":"Der står, at søsteren hedder Lina. Adam er hendes bror."},
{"l":122,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Årstiden, hvor det er varmest, og hvor de fleste har lang ferie. Hvordan staves den?","o":["somer","sommar","sommer","sommær"],"a":"sommer","r":"Vokalen foran m er kort, så der skal to m'er til. Ordet slutter på -er."},
{"l":139,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Vi bager en stor ___ til fødselsdagen.'","o":["kaje","kagge","kaage","kage"],"a":"kage","r":"A'et er langt, så der skal kun ét g. Selvom det kan lyde lidt som j, skrives der g."},
{"l":162,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man to søskende, der er født på samme dag af samme mor?","o":["tvillinger","naboer","fætre","venner"],"a":"tvillinger","r":"Tvillinger er to børn, der bliver født lige efter hinanden. Ordet har noget at gøre med tallet to."},
{"l":180,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå til sidst: 'Kan du cykle'?","o":["punktum","spørgsmålstegn","udråbstegn","komma"],"a":"spørgsmålstegn","r":"Her spørger man om noget, selv om der ikke er et spørgeord. Sætningen begynder med udsagnsordet 'kan', og svaret kan være ja eller nej."},
{"l":201,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et tillægsord i sætningen: 'Vi bor i et gult hus.'","o":["bor","hus","gult","Vi"],"a":"gult","r":"Ordet 'gult' fortæller, hvordan huset ser ud. Ord, der gør det, er tillægsord."},
{"l":222,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad hedder ungen af en kat?","o":["føl","kalv","lam","killing"],"a":"killing","r":"En killing er en ung kat. Føl, kalv og lam er unger af hest, ko og får."},
{"l":240,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er en hovedperson i en historie?","o":["Den, historien mest handler om","Den, der har skrevet bogen","Den, der har tegnet billederne","Den, der læser bogen højt"],"a":"Den, historien mest handler om","r":"Hovedpersonen er den vigtigste person i historien. Det er ham eller hende, vi følger mest."},
{"l":259,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Jeg skriver i mit hæfte med en ___.'","o":["gaffel","blyant","pude","sko"],"a":"blyant","r":"En blyant bruger man til at skrive og tegne med. Med en gaffel spiser man."},
{"l":281,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'En ko, en løve og en mus er alle sammen ___.'","o":["dir","dyrr","dyr","dyyr"],"a":"dyr","r":"Ordet skrives med y og ét r. Der skal ikke i."},
{"l":300,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Magnus står op, før solen er kommet frem. Han hjælper sin far med at fodre køerne.' Hvor bor Magnus nok?","o":["I et højhus i byen","På et skib","Ved en skole","På en gård"],"a":"På en gård","r":"Køer, der skal fodres om morgenen, hører til på en gård."},
{"l":320,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Heksen låste prinsen inde i tårnet. Prinsesse Alma hentede nøglen og slap ham fri.' Hvem er den onde i teksten?","o":["heksen","prinsen","prinsesse Alma","tårnvagten"],"a":"heksen","r":"Heksen gør noget ondt, for hun låser prinsen inde. Alma gør det gode, da hun hjælper ham fri."},
{"l":342,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Bierne samler nektar fra blomsterne og laver ___.'","o":["mælk","honning","uld","smør"],"a":"honning","r":"Bierne laver honning af den søde nektar fra blomsterne."},
{"l":361,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sara og Jonas har fået en ny elev i klassen. Han hedder Tobias og kommer fra Aalborg. Han kan godt lide at tegne.' Hvem er den nye elev?","o":["Sara","Jonas","Tobias","Aksel"],"a":"Tobias","r":"Den anden sætning siger, at den nye elev hedder Tobias. Sara og Jonas går i klassen i forvejen."},
{"l":381,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig for det modsatte af kold?","o":["varrm","varmm","vaarm","varm"],"a":"varm","r":"Ordet har ét r og ét m. Slutningen rm står i mange ord, for eksempel 'arm'."},
{"l":397,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hun smiler og er i godt humør. Hvilket ord er stavet rigtigt?","o":["glad","gladd","glaj","glaad"],"a":"glad","r":"Ordet ender på blødt d. Med t ville det betyde noget helt andet, for eksempel om en isglat vej."},
{"l":421,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'August trak vejret dybt og gik op foran klassen. Hans hænder var kolde. Så begyndte han at fortælle om sin hamster.' Hvordan havde August det, inden han begyndte?","o":["Han var søvnig","Han var nervøs","Han var rasende","Han var ligeglad"],"a":"Han var nervøs","r":"Dyb vejrtrækning og kolde hænder er tegn på, at man er nervøs for at stå foran andre."},
{"l":439,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Rose, tulipan og mælkebøtte hører sammen. Hvad er de alle sammen?","o":["træer","bær","blomster","grøntsager"],"a":"blomster","r":"Alle tre er planter med farvede kronblade. Roser og tulipaner kan man købe i en buket."},
{"l":461,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Seks ___ fik en is af læreren.'","o":["barn","barnet","børnene","børn"],"a":"børn","r":"Flertal af 'et barn' er 'børn'. Efter et tal bruger man ikke den bestemte form 'børnene'."},
{"l":481,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Jeg forstår ikke opgaven og har brug for ___.'","o":["hjælp","jælp","hjælb","hjelp"],"a":"hjælp","r":"Ordet begynder med stumt h foran j og skrives med æ. Til sidst står lp."},
{"l":499,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Samir bærer poserne ind for sin nabo, som er gammel. Bagefter får han en småkage og et stort smil.' Hvorfor får Samir en småkage?","o":["Fordi han har fødselsdag","Fordi naboen vil takke ham","Fordi han har købt den selv","Fordi han har tabt poserne"],"a":"Fordi naboen vil takke ham","r":"Han har hjulpet naboen med poserne. Småkagen og smilet er naboens tak."},
{"l":522,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører sammen med tillægsordet 'tørstig'?","o":["tørklæde","tårn","tørst","tøj"],"a":"tørst","r":"Når man er tørstig, føler man tørst. Et tørklæde har intet med det at gøre, selv om ordet begynder ens."},
{"l":539,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: '___ er himlen blå?'","o":["vorfor","hvorfår","hvoffor","hvorfor"],"a":"hvorfor","r":"Ordet er sat sammen af 'hvor' og 'for'. Begge dele skrives med o."},
{"l":560,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mina har ondt i halsen og feber. Mor ringer til skolen. Derefter laver hun te til Mina.' Hvorfor ringer mor til skolen?","o":["Fordi Mina er blevet syg","Fordi Mina har glemt sin taske","Fordi skolen skal have te","Fordi læreren er blevet syg"],"a":"Fordi Mina er blevet syg","r":"Ondt i halsen og feber betyder, at Mina er syg. Derfor må mor sige det til skolen."},
{"l":581,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Min lillesøster er ___ for mørke.'","o":["bangge","bange","bannge","bangke"],"a":"bange","r":"Her høres ingen k-lyd, så ordet skrives med ng."},
{"l":600,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Et eventyr handler om tre brødre. Hvem af dem klarer det som regel bedst?","o":["den ældste","den mellemste","den yngste","den højeste"],"a":"den yngste","r":"I eventyr fejler de to ældste brødre tit. Så er det den yngste, som ingen troede på, der klarer det."},
{"l":619,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en høflig person?","o":["råber højt og skubber i køen","løber hurtigt og taber sin taske","sover længe og glemmer sin madpakke","siger tak og venter på sin tur"],"a":"siger tak og venter på sin tur","r":"At være høflig er at opføre sig pænt og tage hensyn til andre."},
{"l":639,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du tager den på, når du skal ud i kulden. Find den rigtige stavemåde.","o":["jakke","jake","jacke","jakkæ"],"a":"jakke","r":"A'et er kort, så der skal to k'er. Der skal ikke c med."},
{"l":660,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Vi har idræt på Tirsdag med Jonas.'?","o":["Vi","Tirsdag","idræt","Jonas"],"a":"Tirsdag","r":"Ugedage skrives med lille inde i en sætning. 'Vi' står først, og Jonas er et navn, så de har med rette stort bogstav."},
{"l":681,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du går op ad den for at komme på første sal. Hvilken stavemåde er rigtig?","o":["trape","trabbe","trappe","trappæ"],"a":"trappe","r":"A'et er kort, så der skal to p'er. Ordet slutter på e."},
{"l":699,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Morfar tager sine briller på og holder avisen langt væk. Så sukker han og beder Elias om at læse den lille tekst højt.' Hvorfor beder morfar Elias om hjælp?","o":["Han vil høre Elias øve sig til prøven","Han kan ikke lide at læse aviser","Han har glemt, hvor han har sine briller","Han kan ikke se den lille tekst"],"a":"Han kan ikke se den lille tekst","r":"Han har brillerne på og holder avisen langt væk, men må alligevel opgive. Teksten er for lille til hans øjne."},
{"l":721,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'hun' i sætningen: 'Hun spiller fodbold efter skole.'","o":["stedord","navneord","udsagnsord","tillægsord"],"a":"stedord","r":"'Hun' står i stedet for en piges eller en kvindes navn. Ord, der gør det, er stedord."},
{"l":739,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'kroner' her: 'Ispinden koster 20 kroner.'","o":["pynt til konger","en slags penge","toppe af træer","dele af tænder"],"a":"en slags penge","r":"Vi betaler med kroner i Danmark. Ordet krone kan også være kongens hovedpynt, men her handler det om prisen."},
{"l":759,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Oskar spiller på det røde hold. Hans bedste ven spiller på det blå. I dag spiller de mod hinanden, og Oskar ved ikke rigtig, hvem han skal heppe på.' Hvad er svært for Oskar?","o":["At huske, hvilket hold han er på","At han ikke kan lide farven blå","At hans ven er på det andet hold","At hans ven ikke vil spille med"],"a":"At hans ven er på det andet hold","r":"De er på hvert sit hold, så de kan ikke begge vinde. Det gør Oskar i tvivl."},
{"l":780,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange kommaer skal der være i: 'Jeg kan lide bolde biler bøger og blyanter.'?","o":["ét","tre","fire","to"],"a":"to","r":"Der skal komma efter 'bolde' og efter 'biler'. Foran 'og' står der ikke komma."},
{"l":799,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører til tillægsordet 'stærk'?","o":["styrke","storm","stykke","stilhed"],"a":"styrke","r":"Den, der er stærk, har styrke. Ordene hører til samme familie, selv om vokalen skifter."},
{"l":820,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bedstemor kan ikke huske, hvor hun har lagt sine briller. Hun har ledt i hele stuen. Rasmus peger, og så griner hun, for de sidder på hendes pande.' Hvorfor griner bedstemor?","o":["Rasmus har gemt brillerne","Hun havde dem selv på hovedet","Stuen er meget rodet","Hun har købt et par nye"],"a":"Hun havde dem selv på hovedet","r":"Hun ledte alle steder, og brillerne sad på hendes egen pande. Det er derfor sjovt."},
{"l":838,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form står navneordet i, når der står 'et æble'?","o":["bestemt ental","ubestemt flertal","ubestemt ental","bestemt flertal"],"a":"ubestemt ental","r":"Der er kun ét æble, og det er ikke et bestemt æble. Den bestemte form hedder 'æblet'."},
{"l":859,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Emma får en ny cykel. Jonas ønsker, at han havde den i stedet. Hvordan har Jonas det?","o":["stolt","tilfreds","lettet","misundelig"],"a":"misundelig","r":"Man er misundelig, når man ønsker sig noget, som en anden har."},
{"l":880,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Snart kommer solen frem, / og så går vi alle ___.' Hvilket ord giver rim?","o":["hjem","ud","ned","væk"],"a":"hjem","r":"Frem og hjem slutter på den samme lyd, og derfor rimer de. De andre ord kunne godt passe i sætningen, men de rimer ikke."},
{"l":898,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver gang Luna løfter sit madkasselåg, kommer der en lille hund løbende. Den sætter sig foran hende og kigger med store øjne.' Hvorfor kommer hunden?","o":["Den er bange for madkassen","Den håber at få noget at spise","Den vil gerne lege med låget","Den vil gerne ind i klassen"],"a":"Den håber at få noget at spise","r":"Den kommer, når madkassen åbnes, og sætter sig og tigger. Så vil den have mad."},
{"l":919,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'sandhed'?","o":["gåde","sang","løgn","drøm"],"a":"løgn","r":"Sandheden er det, der virkelig er sket. En løgn er noget, der ikke er sandt, og som man siger med vilje."},
{"l":941,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mie lagde sin yndlingsbog foran sin bedste veninde. Den måtte hun beholde, sagde Mie, så hun kunne huske hende. Mie flyttede nemlig til Jylland på lørdag.' Hvorfor giver Mie sin veninde bogen?","o":["Fordi hun ikke kan lide bogen","Fordi hun har læst den før","For at give hende en fødselsdagsgave","For at veninden kan huske hende"],"a":"For at veninden kan huske hende","r":"Mie flytter til Jylland, og hun siger selv, at bogen skal få veninden til at huske hende."},
{"l":957,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en vulkan?","o":["et bjerg, hvor lava kan komme ud","en flod med varmt vand i bunden","en dyb dal mellem to høje bjerge","en ø, der kun består af fint sand"],"a":"et bjerg, hvor lava kan komme ud","r":"En vulkan er et bjerg med en åbning ned i jorden. Når den går i udbrud, kommer der glødende lava ud."},
{"l":979,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ost, smør og yoghurt er lavet af mælk. Hvad kalder man dem med ét ord?","o":["bagværk","mejerivarer","krydderier","grøntsager"],"a":"mejerivarer","r":"På et mejeri laver man mælk om til for eksempel ost og smør. Derfor hedder de mejerivarer."},
{"l":997,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Det er ___ koldt i dag.'","o":["mejt","meged","meget","mæget"],"a":"meget","r":"Ordet skrives med e, g og t, selvom det lyder anderledes."},
{"l":1020,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad taber Askepot, da hun skynder sig væk fra ballet?","o":["en ring","en hat","en handske","en sko"],"a":"en sko","r":"Askepot taber sin sko. Bagefter leder prinsen efter den pige, som skoen passer på."},
{"l":1039,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Før skolefesten havde Alma 'sommerfugle i maven'. Hvordan havde hun det?","o":["nervøs og spændt","mæt og søvnig","kold og våd","sulten og tørstig"],"a":"nervøs og spændt","r":"Følelsen i maven minder om noget, der flagrer. Man får den, når noget spændende skal ske."},
{"l":1059,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken af linjerne om kaninen er en hel sætning?","o":["Den bløde kanin i haven.","Kaninen hopper i haven.","Hopper rundt i haven.","Min kanin med lange ører."],"a":"Kaninen hopper i haven.","r":"Kun her er både et grundled, 'Kaninen', og et udsagnsled, 'hopper'."},
{"l":1080,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skoven er stille om vinteren. Træerne står nøgne, og mange dyr sover eller er rejst væk. Men i sneen kan man se sporene efter dem, der stadig er her.' Hvad betyder 'nøgne' i teksten?","o":["Uden grene","Meget høje","Uden blade","Fulde af sne"],"a":"Uden blade","r":"Mange træer taber deres blade om vinteren. Træer, der ikke har blade, kan man kalde nøgne."},
{"l":1097,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sommerfuglen starter som et æg. Så bliver den til en larve, som spiser og spiser. Larven bliver til en puppe, og af puppen kommer sommerfuglen.' Hvad kommer lige før puppen?","o":["Ægget","Sommerfuglen","Blomsten","Larven"],"a":"Larven","r":"Rækkefølgen er æg, larve, puppe og sommerfugl. Larven kommer altså lige før puppen."},
{"l":1116,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Elias spurgte: »hvor skal vi hen?«'?","o":["hvor","spurgte","skal","hen"],"a":"hvor","r":"Det første ord i den direkte tale skal have stort bogstav, fordi Elias siger en hel sætning."},
{"l":1139,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du bruger den hver aften ude på badeværelset. Hvilken stavemåde er rigtig?","o":["tanbørste","tandbørste","tandbørsde","tand børste"],"a":"tandbørste","r":"Ordet består af 'tand' og 'børste'. Det skrives i ét ord, og d'et skal med."},
{"l":1159,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'forbavset'?","o":["misundelig","tålmodig","overrasket","ansvarlig"],"a":"overrasket","r":"Forbavset er et andet ord for overrasket. Man bliver det, når noget sker, man ikke havde ventet."},
{"l":1176,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er datid af 'at drikke'?","o":["drikker","drukket","drikke","drak"],"a":"drak","r":"'At drikke' er et uregelmæssigt udsagnsord, der skifter vokal i datid: drak."},
{"l":1197,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en, der praler?","o":["taler højt om, hvor dygtig man selv er","taler lavt, fordi man er genert i klassen","taler venligt til dem, der er kede af det","taler langsomt, så de små børn kan forstå"],"a":"taler højt om, hvor dygtig man selv er","r":"At prale er at vise sig og sige, at man er bedre end andre. Det kan virke irriterende."},
{"l":1219,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'frivilligt'?","o":["at alle er nødt til at gøre det hver dag","at man selv bestemmer, om man vil gøre det","at det koster mange penge at være med","at det kun er noget for voksne mennesker"],"a":"at man selv bestemmer, om man vil gøre det","r":"Det, der er frivilligt, skal ingen tvinge en til. Man må selv vælge."},
{"l":1239,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den runde frugt, der vokser på træer, og som kan være rød eller grøn. Hvilken stavemåde er rigtig?","o":["æbel","ebble","æble","æbble"],"a":"æble","r":"Ordet begynder med æ og har ét b. Det slutter på -le."},
{"l":1257,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Da opgaven blev svær, ville Malte 'opgive'. Hvad ville han?","o":["blive ved med at prøve","prøve noget endnu sværere","vise andre, hvordan man gør","holde op med at prøve"],"a":"holde op med at prøve","r":"Den, der opgiver, stopper, fordi det virker for svært. Heldigvis kan man få hjælp i stedet."},
{"l":1279,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Elefantens snabel er både næse, hånd og slange. Den bruges til at lugte, til at gribe blade med og til at sprøjte vand op over ryggen.' Hvad bruger elefanten ikke snablen til i teksten?","o":["At høre","At lugte","At gribe blade","At sprøjte vand"],"a":"At høre","r":"Teksten nævner lugte, gribe og sprøjte. At høre står der ikke noget om, og det gør elefanter med ørerne."},
{"l":1297,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvis man vil se de fleste stjerner, skal man væk fra byen. Lyset fra lygter og huse gør himlen lysere, så de svage stjerner ikke kan ses.' Hvorfor kan man se færre stjerner i byen?","o":["Fordi der er færre stjerner over byer","Fordi lyset gør himlen lysere","Fordi skyerne altid hænger over byen","Fordi de høje huse står i vejen"],"a":"Fordi lyset gør himlen lysere","r":"Teksten forklarer, at lys fra lygter og huse gør himlen lysere, så de svage stjerner ikke kan ses."},
{"l":1319,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Skildpadden er ___ end haren.'","o":["langsom","langsomt","langsommere","langsomst"],"a":"langsommere","r":"Der sammenlignes med 'end', så det skal være højere grad. Ordet får dobbelt m: langsommere."},
{"l":1339,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Lægen skrev en ___, så Ali kunne hente medicin på apoteket.'","o":["kvittering","billet","invitation","recept"],"a":"recept","r":"En recept er lægens besked til apoteket om, hvilken medicin man skal have. En kvittering får man, når man har betalt."},
{"l":1357,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ole er den stærkeste på holdet, men han råber sjældent. Når nogen falder, er det ham, der rækker hånden ud. Derfor vil alle gerne have ham som anfører.' Hvorfor vil alle have Ole som anfører?","o":["Fordi han hjælper de andre","Fordi han råber højest","Fordi han er den mindste","Fordi han scorer flest mål"],"a":"Fordi han hjælper de andre","r":"Den sidste sætning begynder med 'derfor' og peger tilbage på, at han rækker hånden ud til dem, der falder."},
{"l":1380,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Fordi det var varmt tog vi til stranden.'?","o":["det","varmt","tog","vi"],"a":"varmt","r":"'Fordi det var varmt' er en ledsætning, der står først. Kommaet kommer lige efter den."},
{"l":1399,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en sparsommelig person?","o":["bruger alle sine penge på slik","giver alle sine penge væk","bruger sine penge med omtanke","glemmer sine penge derhjemme"],"a":"bruger sine penge med omtanke","r":"Sparsommelig kommer af 'at spare'. Den, der er det, tænker sig om, før pengene bruges."},
{"l":1418,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen bagte ned, og vandet i åen var næsten væk. Bonden kiggede på sine marker og derefter på den skyfri himmel. Det var tredje uge uden regn.' Hvad bekymrer bonden sig nok om?","o":["At der kommer for meget regn","At åen oversvømmer markerne","At solen går ned for tidligt","At hans marker mangler vand"],"a":"At hans marker mangler vand","r":"Der har ikke været regn i tre uger, og åen er næsten tør. Det er dårligt for bondens afgrøder."},
{"l":1440,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'H.C. Andersen blev født i Odense i 1805. Da han var 14 år, rejste han til København, fordi han gerne ville være med på teatret. Senere blev han kendt over hele verden for sine eventyr.' Hvorfor rejste H.C. Andersen til København?","o":["Han ville være med på teatret","Han ville skrive eventyr","Han skulle gå i skole","Han skulle være skomager"],"a":"Han ville være med på teatret","r":"Teksten siger, at han gerne ville være med på teatret. Eventyrene kom først senere."},
{"l":1458,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ugler flyver næsten uden lyd. Deres fjer er bløde i kanten, så vingerne ikke suser. Det gør, at musen ikke hører uglen komme.' Hvad er fordelen ved de bløde fjer?","o":["De holder uglen varm om natten","Musen hører ikke uglen komme","Uglen kan flyve langt","Uglen kan se i mørke"],"a":"Musen hører ikke uglen komme","r":"Fjerene gør, at uglen flyver næsten uden lyd. Derfor opdager musen ikke, at uglen kommer."},
{"l":1477,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Katten har to gule ___.'","o":["øje","øjet","øjne","øjnene"],"a":"øjne","r":"'Øje' har et særligt flertal: et øje, to øjne. Efter 'to' står den ubestemte form."},
{"l":1498,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken kropsdel sidder midt på armen og kan bøjes?","o":["anklen","hælen","knæet","albuen"],"a":"albuen","r":"Albuen er leddet midt på armen. Knæet ligner den, men det sidder på benet."},
{"l":1518,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord passer: 'Du skal ___, så ingen andre kan høre hemmeligheden.'","o":["hviske","viske","hvisge","hvisske"],"a":"hviske","r":"Når du taler meget stille, skrives ordet med h. Ordet 'viske' uden h betyder at gnide noget ud."},
{"l":1537,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Vi har to lærere i dansk. ___ hedder Mona og Aske.'","o":["Lærere","Lærerne","Lærer","Læreren"],"a":"Lærerne","r":"Nu ved vi, hvilke lærere det drejer sig om. Så står ordet i bestemt flertal: lærerne."},
{"l":1557,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Selvom Maryam var træt, gik hun alligevel til træning. Hun vidste, at holdet manglede spillere. Hvis hun blev hjemme, kunne de ikke stille op til kampen.' Hvorfor tog Maryam til træning?","o":["Fordi hun havde lyst til at løbe","Fordi træneren havde ringet hjem","Fordi holdet havde brug for hende","Fordi hendes mor sagde, hun skulle"],"a":"Fordi holdet havde brug for hende","r":"Holdet manglede spillere og kunne ikke stille op uden hende. Hun tænkte på de andre, selv om hun var træt."},
{"l":1575,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassen kiggede på det nye ur i gymnastiksalen. Det hang helt skævt. Pedellen, der havde sat det op, hed Ove. Han lo og sagde, at hans briller lå derhjemme.' Hvorfor hang uret skævt?","o":["Væggen var skæv","Uret var gået i stykker","Eleverne havde rørt ved det","Ove kunne ikke se ordentligt"],"a":"Ove kunne ikke se ordentligt","r":"Han havde ikke sine briller med, da han hængte uret op. Så kunne han ikke se, at det hang skævt."},
{"l":1597,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer i sætningen: 'Vi låner bøger på ___, og bagefter skal vi aflevere dem igen.'","o":["biblioteket","rådhuset","stationen","apoteket"],"a":"biblioteket","r":"Biblioteket låner bøger ud gratis. På apoteket køber man medicin."},
{"l":1619,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad passer bedst: 'Efter regnen var der store ___ på vejen, som vi kunne hoppe i.'","o":["solstråler","vandpytter","stjerner","snefnug"],"a":"vandpytter","r":"Regnvand samler sig i små fordybninger på vejen, og dem kalder vi vandpytter."},
{"l":1638,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tog tager længere tid end fly, men de sender langt mindre forurening ud. Derfor vælger nogle familier toget, når de skal på ferie.' Hvorfor vælger nogle familier toget?","o":["Toget er hurtigere","Toget er billigere","Toget forurener mindre","Toget er sjovere"],"a":"Toget forurener mindre","r":"Teksten nævner, at toget sender langt mindre forurening ud, og 'derfor' viser, at det er grunden."},
{"l":1657,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt ordet i datid: 'Hun ___ den tunge kasse op ad trappen i morges.'","o":["bærer","bære","båret","bar"],"a":"bar","r":"'At bære' skifter vokal i datid og hedder 'bar'."},
{"l":1680,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et gråligt, skinnende metal. Vælg den rigtige stavemåde.","o":["sølv","sølw","sølf","søllv"],"a":"sølv","r":"Ordet ender på lv med stumt v, ligesom 'halv' og 'gulv'."},
{"l":1699,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Hun siger altid sandheden. Hun er en ___ pige.'","o":["erlig","ærlig","ærli","ærrlig"],"a":"ærlig","r":"Ordet begynder med æ og ender på -lig med stumt g."},
{"l":1718,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Er du helt ___ på, at du låste døren?'","o":["siker","sikkær","sikker","sigger"],"a":"sikker","r":"I'et er kort, så der skal to k'er. Ordet slutter på -er."},
{"l":1737,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Held og ___ til prøven!'","o":["lyke","lygge","lykkæ","lykke"],"a":"lykke","r":"Ordet skrives med y og to k'er. Det lyder blødt, men der skal ikke g."},
{"l":1756,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Han bærer rygsækken på ___.'","o":["ryggen","rygen","ryggenn","rykgen"],"a":"ryggen","r":"I grundformen er der ét g, men når endelsen -en kommer på, bliver g'et dobbelt, fordi vokalen er kort."},
{"l":1777,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Jeg vil gerne ___ at spille klaver.'","o":["lærer","lære","lærte","lært"],"a":"lære","r":"Efter 'vil' står udsagnsordet i navneform uden -r: lære."},
{"l":1799,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at have 'feber'?","o":["at man har ondt i en tand","at huden klør efter et myggestik","at kroppen er varmere end normalt","at man har brækket en knogle"],"a":"at kroppen er varmere end normalt","r":"Ved feber stiger kroppens temperatur. Det er tit et tegn på, at kroppen kæmper mod en sygdom."},
{"l":1818,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver dag satte Ida en ny klods på tårnet. Efter en uge var tårnet så højt, at hun måtte stå på en stol. Lillebror kiggede på det med store øjne, men holdt fingrene for sig selv.' Hvad betyder 'holdt fingrene for sig selv'?","o":["At han talte på fingrene","At han havde ondt i fingrene","At han gemte sine hænder i lommen","At han ikke rørte ved det"],"a":"At han ikke rørte ved det","r":"Det er en talemåde. Han havde lyst, men lod være med at røre ved tårnet."},
{"l":1837,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'varm' står i højeste grad?","o":["varmest","varmere","varm","varmt"],"a":"varmest","r":"Rækken er varm, varmere, varmest. Højeste grad er den sidste."},
{"l":1859,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt ind i sætningen: 'Hunden ___ med halen, da vi kom hjem.'","o":["nikkede","logrede","bukkede","vinkede"],"a":"logrede","r":"En hund logrer med halen, når den er glad. Man nikker med hovedet og vinker med hånden."},
{"l":1879,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Vejret ___ dårligt om eftermiddagen.'","o":["bleu","blew","blev","blæv"],"a":"blev","r":"Datid af 'blive' skrives med e og ender på v."},
{"l":1898,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hele klassen ___ i kø ved boden i går.'","o":["stog","stodd","stot","stod"],"a":"stod","r":"Datid af 'stå' ender på blødt d. Der er ét d."},
{"l":1917,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Bageren laver det af mel og vand hver morgen. Hvordan staves det?","o":["brød","brøt","brødd","brøj"],"a":"brød","r":"Ordet ender på blødt d, og der er ét d."},
{"l":1936,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Min bror fik en ___ på knæet, da han faldt.'","o":["skae","skade","skadde","skaje"],"a":"skade","r":"Ordet har blødt d i midten. A'et er langt, så der er kun ét d."},
{"l":1957,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er rigtigt: 'Min rygsæk er ___ end din.'","o":["tung","tungest","tungere","tungt"],"a":"tungere","r":"To rygsække sammenlignes med 'end'. Så skal tillægsordet stå i højere grad."},
{"l":1977,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rikke var næsten færdig med puslespillet. Hun havde arbejdet på det i tre uger. Men der manglede én brik i himlen, og hunden kiggede væk.' Hvad antyder den sidste sætning?","o":["At hunden er træt af puslespil","At hunden ikke kan se himlen","At hunden gerne vil ud at gå","At hunden måske har taget brikken"],"a":"At hunden måske har taget brikken","r":"At hunden kigger væk, er en sjov måde at antyde, at den har dårlig samvittighed."},
{"l":1995,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi ser kun den ene side af månen fra jorden. Det skyldes, at månen drejer om sig selv lige så langsomt, som den kredser om jorden. Bagsiden blev først set, da rumskibe fløj omkring den.' Hvorfor så man først bagsiden med rumskibe?","o":["Fordi bagsiden aldrig vender mod jorden","Fordi månen er for langt væk","Fordi månen kun skinner om natten","Fordi bagsiden er mørk hele tiden"],"a":"Fordi bagsiden aldrig vender mod jorden","r":"Vi ser altid den samme side af månen fra jorden. Bagsiden kunne man kun se ved at flyve derhen."},
{"l":2017,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'lavvandet', når vi taler om en sø?","o":["stor","dyb","ren","rund"],"a":"dyb","r":"I en lavvandet sø er der kort til bunden, og i en dyb sø er der langt ned."},
{"l":2040,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'forbløffet'?","o":["bekymret","irriteret","overrasket","skuffet"],"a":"overrasket","r":"Den, der er forbløffet, er meget overrasket og havde slet ikke ventet det, der skete."},
{"l":2058,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nogle dyr har farver, der ligner omgivelserne. En brun hare er svær at se på en mark, og sneharen er hvid om vinteren. Det kaldes camouflage.' Hvad er formålet med camouflage?","o":["At holde sig varm om vinteren","At kunne finde en mage","At se flot ud for andre","At være svær at få øje på"],"a":"At være svær at få øje på","r":"Teksten viser eksempler på dyr, der er svære at se, fordi de ligner deres omgivelser."},
{"l":2077,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvem er 'tålmodig'?","o":["en, der roligt kan vente længe","en, der altid kommer for sent","en, der hurtigt bliver sur","en, der tit glemmer sine ting"],"a":"en, der roligt kan vente længe","r":"Den, der er tålmodig, bliver ikke urolig af at vente. Det modsatte er utålmodig."},
{"l":2098,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige datidsform: 'I går ___ vi pizza.'","o":["spisde","spiste","spisste","spisede"],"a":"spiste","r":"Datid af 'spise' ender på -te. Der er kun ét s efter i'et."},
{"l":2117,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige datidsform: 'I går ___ vi til stranden.'","o":["cykled","cykelde","cyklede","cykkelede"],"a":"cyklede","r":"Datid af 'cykle' ender på -ede. Der er ét k, og e'et fra 'cykel' falder væk."},
{"l":2137,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find stedordet: 'Efter skole cyklede hun hjem fra stranden.'","o":["skole","cyklede","stranden","hun"],"a":"hun","r":"'Hun' står i stedet for et navn. Derfor er det et stedord."},
{"l":2157,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bagefter var der ingen, der kunne huske, hvem der begyndte at grine. Men snart lå hele klassen hen over bordene, og selv læreren måtte tørre øjnene.' Hvad betyder 'tørre øjnene' her?","o":["Han grinede, så tårerne løb","Han var blevet ked af det","Han havde fået noget i øjet","Han var meget træt"],"a":"Han grinede, så tårerne løb","r":"Alle griner, og læreren er med. Han tørrer tårer væk, fordi han griner så meget."},
{"l":2175,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der findes omkring 7.000 sprog i verden. Mange af dem tales af meget få mennesker. Når der ikke er nogen tilbage, der kan et sprog, forsvinder sproget.' Hvad er teksten mest om?","o":["At sprog er svære at lære","At mange sprog kan forsvinde","At man kan lære 7.000 sprog","At de fleste taler engelsk"],"a":"At mange sprog kan forsvinde","r":"Teksten forklarer, at mange sprog kun tales af få mennesker, og at de kan forsvinde."},
{"l":2197,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'men' i sætningen: 'Det regner, men vi går alligevel ud.'","o":["forholdsord","navneord","bindeord","udsagnsord"],"a":"bindeord","r":"'Men' binder to sætninger sammen og viser en modsætning. Så er det et bindeord."},
{"l":2220,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'tale under fire øjne'?","o":["at man har briller på, mens man taler","at fire personer taler på én gang","at man ser hinanden dybt i øjnene","at to personer taler alene sammen"],"a":"at to personer taler alene sammen","r":"To personer har tilsammen fire øjne. Vendingen betyder, at ingen andre hører med."},
{"l":2238,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Som lille byggede Jeppe altid huler under bordet. I dag er han voksen og tegner huse for folk. Hans mor siger, at det ikke overrasker hende.' Hvad er Jeppes job nok?","o":["Arkitekt","Tømrer","Bager","Postbud"],"a":"Arkitekt","r":"En, der tegner huse, er arkitekt. Hans leg med huler som barn peger på det samme."},
{"l":2257,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er udsagnsleddet: 'Alle eleverne skal læse en bog i ferien.'","o":["Alle eleverne","skal læse","en bog","i ferien"],"a":"skal læse","r":"'Skal' og 'læse' er begge udsagnsord og udgør tilsammen udsagnsleddet."},
{"l":2278,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig: 'Min ___ er fire år og går i børnehave.'","o":["lilebror","lillebroer","lillebror","lillebrår"],"a":"lillebror","r":"Ordet skrives med to l'er som i 'lille'. Slutningen er 'bror' med o."},
{"l":2297,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den store bygning med bassin, hvor du kan få undervisning i crawl. Hvilket ord er stavet rigtigt?","o":["svømehal","svømmehall","svømme hal","svømmehal"],"a":"svømmehal","r":"Ordet skrives i ét ord med to m'er og ét l til sidst."},
{"l":2317,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er grundleddet i spørgsmålet: 'Hvornår kommer toget til Aarhus?'","o":["toget","kommer","Hvornår","til Aarhus"],"a":"toget","r":"Spørg: Hvad kommer? Det gør toget. I spørgsmål står grundleddet ofte efter udsagnsleddet."},
{"l":2337,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bøger er som venner, sagde bibliotekaren. Nogle møder man én gang, og andre vender man tilbage til, år efter år.' Hvad vil bibliotekaren sige?","o":["At venner kan læse bøger højt","At nogle bøger holder man af hele livet","At man kun må låne en bog én gang","At bøger er bedre end venner"],"a":"At nogle bøger holder man af hele livet","r":"Sammenligningen viser, at nogle bøger bliver ved med at være vigtige, ligesom gode venner."},
{"l":2355,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen skinnede, men Magnus havde ikke set det. Han havde siddet i tre timer med det samme spil og stadig ikke vundet. Da han endelig så op, var solen væk, og hans ven var gået.' Hvad vil teksten sige?","o":["At man ikke skal spille spil om dagen","At vennen var en dårlig ven","At man kan gå glip af noget ved at spille","At spillet var for svært til Magnus"],"a":"At man kan gå glip af noget ved at spille","r":"Magnus mistede både solen og sin ven, mens han sad med spillet."},
{"l":2377,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led mangler i 'Legede i sneen hele dagen'?","o":["udsagnsleddet","navneordet","forholdsordet","grundleddet"],"a":"grundleddet","r":"Vi ved, hvad der skete, men ikke hvem der legede. Der mangler et grundled."},
{"l":2397,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Anders fandt pungen, talte han pengene to gange. Det var nok til den cykel, han drømte om. Men inde i pungen lå også et skolekort med et billede af en lille pige. Han tog sin jakke på og gik hen til skolen.' Hvad vil Anders nok?","o":["Aflevere pungen til pigen","Købe sin nye cykel med det samme","Vise pungen til sine venner i klassen","Gemme pengene hjemme i sin skuffe"],"a":"Aflevere pungen til pigen","r":"Han kommer i tvivl, da han ser billedet af pigen. At han går hen til skolen, viser, at han vil give den tilbage."},
{"l":2415,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Læreren spurgte, om nogen havde set, hvem der tegnede på væggen. Der blev meget stille. Otto kiggede på sine sko, og Bjørk kiggede på Otto.' Hvad ved Bjørk nok?","o":["At læreren allerede ved, hvem det er","At Otto ved noget om tegningen","At ingen har set noget","At Bjørk selv har tegnet på væggen"],"a":"At Otto ved noget om tegningen","r":"Bjørk kigger på Otto i stedet for at sige noget. Det tyder på, at Otto ved noget."},
{"l":2437,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'løb' i sætningen: 'Det lange løb gav hende ondt i benene.'","o":["udsagnsord","tillægsord","navneord","stedord"],"a":"navneord","r":"Her kan man sige 'et løb', og 'lange' fortæller, hvordan det var."},
{"l":2459,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Jeg kan ikke lege i dag. Jeg skal ___ til tandlæge.'","o":["nemli","nemmelig","nemlik","nemlig"],"a":"nemlig","r":"Ordet ender på -lig med stumt g. Der er kun ét m."},
{"l":2478,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lærke havde for første gang klaret prøven bedre end Stine. Hun gik hen til Stine med et stort smil. Da hun så Stines øjne, gemte hun papiret bag ryggen og spurgte, om de skulle spille bold.' Hvorfor gemte Lærke papiret?","o":["Hun kunne se, at Stine var ked af det","Hun blev bange for at miste det","Hun skammede sig over sit resultat","Hun ville hellere spille bold alene"],"a":"Hun kunne se, at Stine var ked af det","r":"Hun ser på Stines øjne, at hun er ked af det. Så vil hun ikke prale og skifter emne."},
{"l":2497,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tre af ordene er navneord. Hvilket er et tillægsord?","o":["ven","venlig","venskab","veninde"],"a":"venlig","r":"Man kan sige en ven, et venskab og en veninde. 'Venlig' fortæller, hvordan nogen er."},
{"l":2516,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Det var bare en helt ___ dag.'","o":["alminnelig","almindeli","almindelig","allmindelig"],"a":"almindelig","r":"Ordet har ét l i starten og stumt d i midten. Det ender på -lig."},
{"l":2535,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Bogen om rumraketter var meget ___.'","o":["interresant","interesant","interressant","interessant"],"a":"interessant","r":"Ordet skrives med ét r i midten og to s'er. Det er et af de ord, man må huske."},
{"l":2557,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'at' i sætningen: 'Jeg håber, at du kommer.'","o":["bindeord","forholdsord","udsagnsord","stedord"],"a":"bindeord","r":"Her binder 'at' to sætninger sammen. Så er det et bindeord."},
{"l":2577,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ved Grenen nord for Skagen mødes to have, Skagerrak og Kattegat. Man kan se bølgerne støde sammen. Det er farligt at bade dér, fordi strømmen er stærk.' Hvorfor er det farligt at bade dér?","o":["Fordi vandet er for koldt","Fordi strømmen er for stærk","Fordi der er for mange turister","Fordi der ligger skibe i vandet"],"a":"Fordi strømmen er for stærk","r":"Teksten forklarer, at det er farligt at bade, fordi strømmen er stærk, når de to have mødes."},
{"l":2595,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Forskere har opdaget, at krager kan genkende ansigter. Hvis en person har skræmt dem, kan de huske det i flere år og skælde ud, når personen kommer forbi.' Hvad fortæller opdagelsen om krager?","o":["At de er meget farlige dyr","At de ikke kan lide mennesker","At de har en god hukommelse","At de kan tale med hinanden"],"a":"At de har en god hukommelse","r":"Krager kan huske et ansigt i flere år. Det viser en god hukommelse."},
{"l":2617,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken række viser ordklasserne i sætningen 'Hun læser bøger.'?","o":["navneord, udsagnsord, stedord","stedord, navneord, udsagnsord","stedord, udsagnsord, tillægsord","stedord, udsagnsord, navneord"],"a":"stedord, udsagnsord, navneord","r":"'Hun' er et stedord, 'læser' et udsagnsord, og 'bøger' et navneord."},
{"l":2639,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Apparatet, du ser film og nyheder på i stuen. Hvordan staves det?","o":["fjernsyn","fjærnsyn","fjernsynn","fjensyn"],"a":"fjernsyn","r":"Ordet består af 'fjern' og 'syn' og skrives med e."},
{"l":2656,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vejret kan 'påvirke' ens humør. Hvad betyder det?","o":["at vejret bliver bestemt af humøret","at vejret har indflydelse på humøret","at vejret bliver kendt i hele byen","at vejret ikke betyder noget for det"],"a":"at vejret har indflydelse på humøret","r":"Det, der påvirker noget, er med til at ændre det. Solskin kan for eksempel gøre os gladere."},
{"l":2677,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Æblerne i kurven er ___.'","o":["rød","rødt","røde","rødme"],"a":"røde","r":"Der er flere æbler, så tillægsordet står i flertal: røde."},
{"l":2696,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den store butik, hvor du køber mad til hele ugen. Hvordan staves den?","o":["supermarket","supermaked","super marked","supermarked"],"a":"supermarked","r":"Ordet består af 'super' og 'marked' og skrives i ét ord. Det ender på d."},
{"l":2715,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Toget forsvinder ind i bjerget gennem en lang ___.'","o":["tunnel","tunel","tunnell","tonnel"],"a":"tunnel","r":"Ordet skrives med to n'er i midten og ét l til sidst."},
{"l":2737,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord i sætningen skal skrives med stort: 'Min farmor læser om danske konger i kolding.'","o":["danske","kolding","konger","farmor"],"a":"kolding","r":"Kolding er en by og et egennavn. 'Danske' skrives med småt, selv om det handler om et land."},
{"l":2757,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der står på skiltet, at man kun må fodre ænderne med korn. Brød kan nemlig give dem sygdomme, og det, de ikke spiser, gør vandet beskidt.' Hvad er skiltets formål?","o":["At sælge korn til besøgende","At fortælle om ænders liv","At beskytte ænderne og vandet","At holde børn væk fra søen"],"a":"At beskytte ænderne og vandet","r":"Reglen skal holde ænderne raske og vandet rent. Det er det, teksten forklarer."},
{"l":2775,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I 1969 gik det første menneske på månen. Mange familier sad oppe om natten og så det på et lille fjernsyn. Der var ikke mange, der havde troet, at det kunne lade sig gøre.' Hvad viser det, at folk sad oppe om natten?","o":["At de ikke kunne sove den nat","At fjernsynet kun sendte om natten","At de var bange for månen","At det var noget helt særligt for dem"],"a":"At det var noget helt særligt for dem","r":"De blev oppe om natten for at se det. Det gør man kun, når noget er helt særligt."},
{"l":2797,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hele grundleddet: 'Den gamle mand med stokken gik langsomt over gaden.'","o":["Den gamle mand med stokken","gik langsomt over gaden","langsomt over gaden","over gaden"],"a":"Den gamle mand med stokken","r":"Spørg: Hvem gik? Det gjorde den gamle mand med stokken. Alle ordene fortæller, hvem det er."},
{"l":2820,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En historie med prinsesser, trolde og magi. Vælg den rigtige stavemåde.","o":["æventyr","eventyr","eventyrr","eventyyr"],"a":"eventyr","r":"Ordet begynder med e og slutter på -tyr med y."},
{"l":2838,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører til udsagnsordet 'bryde'?","o":["bro","brød","brud","brug"],"a":"brud","r":"Når noget brydes, opstår der et brud, for eksempel et benbrud. Vokalen skifter, som den tit gør i ordfamilier."},
{"l":2860,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordet i sætningen: 'Katten gemmer sig under sengen.'","o":["gemmer","sengen","sig","under"],"a":"under","r":"'Under' viser, hvor katten er i forhold til sengen. Forholdsord viser netop forholdet mellem ting i sted eller tid."},
{"l":2875,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'sjælden' i sætningen: 'Det er en sjælden fugl i Danmark.'","o":["almindelig","smuk","lille","farlig"],"a":"almindelig","r":"En sjælden fugl ser man kun få af. En almindelig fugl ser man tit, så de to ord er hinandens modsætninger."},
{"l":2897,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'dyb', når man taler om en sø?","o":["kold","lavvandet","klar","stille"],"a":"lavvandet","r":"I en dyb sø er der langt ned til bunden. I en lavvandet sø kan man måske stå på bunden."},
{"l":2915,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld sætningen: 'Min kusine ___ i et gult hus ved havnen.'","o":["bo","boer","bor","borr"],"a":"bor","r":"Navnemåden er 'at bo'. I nutid sætter man bare et r på."},
{"l":2937,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord i sætningen er et stedord: 'Hun købte en blå cykel.'","o":["købte","blå","cykel","Hun"],"a":"Hun","r":"'Hun' står i stedet for et navn. Derfor kaldes det et stedord."},
{"l":2957,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan erstatte 'forsigtigt' i sætningen: 'Hun gik forsigtigt hen over isen.'","o":["varsomt","hastigt","muntert","larmende"],"a":"varsomt","r":"Varsomt betyder forsigtigt, altså uden at tage chancer. Hastigt ville være det stik modsatte på glat is."},
{"l":2975,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvorfor rejste H.C. Andersen som ung fra Odense til København?","o":["Han skulle gå i lære som skomager","Han drømte om at komme til teatret","Han var blevet sendt væk af kongen","Han skulle læse til læge"],"a":"Han drømte om at komme til teatret","r":"Andersen var 14 år, da han rejste til København. Han drømte om teatret, men blev i stedet verdensberømt som forfatter."},
{"l":2995,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes det trin i en sommerfugls liv, hvor den ligger stille og forvandles?","o":["larve","yngel","puppe","frø"],"a":"puppe","r":"Larven spinder sig ind og bliver til en puppe. Inde i puppen forvandles den til en sommerfugl."},
{"l":3014,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld: 'Skolen ___ klokken otte hver mandag.'","o":["begynde","begynner","bekynder","begynder"],"a":"begynder","r":"Ordet står i nutid og skal have r til sidst. D'et før -er skal med, selvom det næsten ikke høres."},
{"l":3036,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig? 'Hun ___ sig en hund til jul.'","o":["ønsker","ønske","ønsger","ynsker"],"a":"ønsker","r":"Ordet står i nutid og ender på -er. Det staves med sk, selvom det kan lyde som sg."},
{"l":3055,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes den smeltede sten, der flyder ud af en vulkan?","o":["aske","lava","kul","ler"],"a":"lava","r":"Nede under jorden hedder den smeltede sten magma. Når den kommer op og flyder ud, kaldes den lava."},
{"l":3074,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i teksten skal have stort: 'Vores lærer sagde: »i dag skriver vi digte.«'?","o":["dag","skriver","i","digte"],"a":"i","r":"Direkte tale, der er en hel sætning, begynder med stort. Det gælder også korte ord som 'i'."},
{"l":3092,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken periode i Danmarks oldtid hører jægere med flintøkser hjemme i?","o":["bronzealderen","jernalderen","vikingetiden","stenalderen"],"a":"stenalderen","r":"Oldtidens perioder har navn efter det vigtigste materiale til redskaber. Flint er en sten, så flintøksen hører til stenalderen."},
{"l":3113,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'I går ___ hunden hele eftermiddagen under bordet.'","o":["lå","lagde","lagte","ligged"],"a":"lå","r":"Hunden var i ro, så det er 'ligge'. I datid hedder det et kort ord med å."},
{"l":3135,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et bindeord: 'Silas læser, mens hans søster øver sig på fløjte.'","o":["læser","mens","hans","øver"],"a":"mens","r":"'Mens' binder to sætninger sammen og viser, at to ting sker samtidig."},
{"l":3154,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Edderkopper er ikke insekter. Insekter har seks ben og tre kropsdele. Edderkopper har otte ben og to kropsdele, og de har ingen vinger. De hører til en gruppe dyr, som også tæller mider og skorpioner.' Hvordan kan du vide, at et dyr med otte ben ikke er et insekt?","o":["Fordi insekter altid har vinger","Fordi insekter er mindre end mider","Fordi insekter har seks ben","Fordi insekter har to kropsdele"],"a":"Fordi insekter har seks ben","r":"Teksten nævner seks ben som kendetegn for insekter. Otte ben passer ikke, så dyret kan ikke være et insekt."},
{"l":3175,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord er dannet af 'invitere'? 'Alle i klassen fik en ___ til festen.'","o":["inviteret","inviterer","inviterede","invitation"],"a":"invitation","r":"Invitation er navneordet, og man kan sætte 'en' foran. De andre er former af udsagnsordet."},
